      var matched1 = false;
      if (!matched1 && select1 == 'TeststandAdministrator') {
        matched1 = true;
        groups[locals.loopingIndex] = 'Administrator'; // Rename Entry to Teststand Group
      }
      if (!matched1 && select1 == 'Users') {
        matched1 = true;
        groups[locals.loopingIndex] = 'Operator'; // Rename Entry to Teststand Group
      }
    }
  }
  for (final element in ts.iterate(locals.teststandGroups)) {
