      // Verify User is in the group. Add if necessary
      if (ts.cond(
        'FindIndex(Parameters.userGroups,Parameters.GroupName)  != "" //If the user is part of this group then add or verify, else delete',
      )) {
        locals.alreadyInGroup = false;
