          if (locals.members.AsPropertyObject.GetValStringByOffset(locals.idx, 0) == user.AsUser.LoginName) {
            locals.alreadyInGroup = true; // Remove User From Group
            ts.eval(
              'RunState.Engine.UsersFile.AsPropertyObjectFile.IncChangeCount()',
