          ); // Add User to Group
          ts.eval(
            'RunState.Engine.UsersFile.AsPropertyObjectFile.IncChangeCount()',
          ); // Increment Changecount of User File
          locals.fileChanged = true;
        }
        // Delete User if its in the Group
      } else {
        for (locals.idx = 0; locals.idx < (locals.members.AsPropertyObject.GetNumElements() as num); locals.idx += 1) {
          if (locals.members.AsPropertyObject.GetValStringByOffset(locals.idx, 0) == user.AsUser.LoginName) {
            locals.members.AsPropertyObject.DeleteElements(locals.idx, 1, 0); // Remove User From Group
            ts.eval(
              'RunState.Engine.UsersFile.AsPropertyObjectFile.IncChangeCount()',
            ); // Increment Changecount of User File
